请对以下 case 进行三维加权评分。

=== case_id ===
Case-09-weather-care-016

=== 用户原始指令 (query.txt) ===
帮我做个极简风格的天气关怀卡片，加个晴天的氛围渐变，中间放个大太阳的图标，卡片里嵌个小的天气组件。下面做个能滚动的列表，把接下来几天的天气和感冒指数列出来，要是温度有异常记得变色，点一下就能跳到天气应用。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我做个极简风格的天气关怀卡片，加个晴天的氛围渐变，中间放个大太阳的图标，卡片里嵌个小的天气组件。下面做个能滚动的列表，把接下来几天的天气和感冒指数列出来，要是温度有异常记得变色，点一下就能跳到天气应用。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hww://www.huawei.com/totemweather?enterType=share&cityCode="
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询地区名称，用于卡片标题辅助展示。",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureC": {
            "type": "number",
            "description": "当前摄氏温度数值，用于判断温度异常时的高亮颜色。",
            "sampleValue": 36
          },
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "36°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "晴"
          },
          "coldLevel": {
            "type": "string",
            "description": "当前感冒指数。",
            "sampleValue": "较低"
          }
        },
        "daily": [
          {
            "weekday": {
              "type": "string",
              "description": "第一天预报的星期文本。",
              "sampleValue": "今天"
            },
            "condition": {
              "type": "string",
              "description": "第一天白天天气现象。",
              "sampleValue": "晴"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第一天温度范围展示文本。",
              "sampleValue": "27° / 36°"
            },
            "coldLevel": {
              "type": "string",
              "description": "第一天感冒指数。",
              "sampleValue": "较低"
            }
          },
          {
            "weekday": {
              "type": "string",
              "description": "第二天预报的星期文本。",
              "sampleValue": "明天"
            },
            "condition": {
              "type": "string",
              "description": "第二天白天天气现象。",
              "sampleValue": "多云"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第二天温度范围展示文本。",
              "sampleValue": "26° / 33°"
            },
            "coldLevel": {
              "type": "string",
              "description": "第二天感冒指数。",
              "sampleValue": "低"
            }
          },
          {
            "weekday": {
              "type": "string",
              "description": "第三天预报的星期文本。",
              "sampleValue": "周六"
            },
            "condition": {
              "type": "string",
              "description": "第三天白天天气现象。",
              "sampleValue": "阵雨"
            },
            "temperatureRangeText": {
              "type": "string",
              "description": "第三天温度范围展示文本。",
              "sampleValue": "24° / 30°"
            },
            "coldLevel": {
              "type": "string",
              "description": "第三天感冒指数。",
              "sampleValue": "中"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/sunny.png",
      "description": "彩色太阳天气图标，适合晴天状态、天气卡片主视觉和日光氛围表达。"
    }
  ]
}

